    //
    // for (i = 0; i < M; i++)
    //   for (j = 0; j < N; j++) {
    //     for (k = i+1; k < M; k++)
    //       B[i][j] += A[k][i] * B[k][j];
    //     B[i][j] = alpha * B[i][j];
    //   }
    //
    // As analyzed in the original code, all reads of B[k][j] use the
    // original B (no in-place dependence across rows), so we can write:
    //
    //   B_out[i][j] = alpha * ( B_in[i][j] +
    //                           sum_{k = i+1..M-1} A[k][i] * B_in[k][j] )
    //
    // Mapping indices to Halide:
    //   A[k][i]  -> A_param(i, k)   (column i, row k)
    //   B[k][j]  -> B_param(j, k)   (column j, row k)
    //   B[i][j]  -> B_param(j, i)   (column j, row i)
    //
    // We implement "k from i+1..M-1" via a select inside a reduction
    // over k in [0..M-1], which keeps the expression simple and legal
    // for Halide's reduction helpers.
    Func trmm("trmm");

    Expr alpha_expr = Expr(alpha);
    Expr zero = cast<num_t>(0);

    trmm(j, i) = alpha_expr *
                 (B_param(j, i) +
                  sum(select(k > i,
                             A_param(i, k) * B_param(j, k),
                             zero)));

    // Optimized CPU schedule for trmm:
    //   - Use tiles over (j,i) for better cache locality.
    //   - Parallelize over tiles in the i (row) dimension.
    //   - Vectorize across j (contiguous in memory).
    const int vec_width = 8;   // fixed vector width (works well for float/double)
    const int tile_i    = 32;  // rows per tile
    const int tile_j    = 64;  // columns per tile

    Var io("io"), jo("jo"), ii("ii"), ji("ji");

    // Ensure the bounds match the intended problem size, then tile/parallelize.
    trmm
        .bound(i, 0, m)
        .bound(j, 0, n)
        // j is the innermost (x) dimension, i is outer (y) by default.
        .tile(j, i, jo, io, ji, ii, tile_j, tile_i)
        .parallel(io)            // distribute tiles of rows across cores
        .vectorize(ji, vec_width); // vectorize along contiguous j

    // Compile the kernel to machine code for the host
    Target target = get_host_target();
    trmm.compile_jit(target);

    // Output buffer for the result (same logical layout as B)
    Buffer<num_t, 2> B_result(n, m);

    // Time the execution
    auto start = std::chrono::high_resolution_clock::now();

    trmm.realize(B_result);

    auto end = std::chrono::high_resolution_clock::now();
    auto duration = std::chrono::duration<long double>(end - start);

    // Optionally print the result to avoid dead-code elimination
