    // Problem sizes (compile-time constants from PolyBench headers)
    int m = M;
    int n = N;

    // Scalars and arrays
    num_t alpha;
    // Buffer layout: width = number of columns, height = number of rows
    // A: M x M  -> Buffer(m, m) accessed as A(j, i) == A[i][j] in C
    // B: M x N  -> Buffer(n, m) accessed as B(j, i) == B[i][j] in C
    Buffer<num_t, 2> A(m, m);
    Buffer<num_t, 2> B(n, m);

    // Initialize data
    init_array(m, n, &alpha, A, B);

    // Halide ImageParams corresponding to A and B (read-only views)
    ImageParam A_param(type_of<num_t>(), 2, "A_param");
    ImageParam B_param(type_of<num_t>(), 2, "B_param");
    A_param.set(A);
    B_param.set(B);

    // Vars: i = row index, j = column index in the original C layout.
    Var i("i"), j("j");

    // Reduction domain over k in [0, m)
    RDom k(0, m, "k");

    // ------------------------------------------------------------------
    // Kernel: B := alpha * A^T * B, where A is unit lower-triangular.
    //
    // Original C kernel:
    //
    // for (i = 0; i < M; i++)
    //   for (j = 0; j < N; j++) {
    //     for (k = i+1; k < M; k++)
    //       B[i][j] += A[k][i] * B[k][j];
    //     B[i][j] = alpha * B[i][j];
    //   }
    //
    // Dependency analysis:
    //   - Reads of B[k][j] always use k > i.
    //   - Because the outer loop walks i from 0..M-1, rows k > i
    //     have not yet been overwritten, so B[k][j] is the original B.
    //   - Therefore each output row i depends only on:
    //       { B_in[i][j], B_in[k>i][j], A[k>i][i] }
    //     and not on any B_out[*][*].
    //
    // So we can write the final value in closed form as:
    //
    //   B_out[i][j] = alpha * ( B_in[i][j] +
    //                           sum_{k = i+1..M-1} A[k][i] * B_in[k][j] )
    //
    // Mapping indices to Halide buffer coordinates:
    //   A[k][i]  -> A_param(i, k)   (A stored as A(col=j, row=i))
    //   B[k][j]  -> B_param(j, k)
    //   B[i][j]  -> B_param(j, i)
    //
    // We implement "k from i+1..M-1" via a select inside a reduction over k in [0..M-1].
    // This keeps the algorithm purely functional and easy to schedule.
    // ------------------------------------------------------------------
    Func trmm("trmm");

    Expr alpha_expr = Expr(alpha);
    Expr zero = cast<num_t>(0);

    trmm(j, i) = alpha_expr *
                 (B_param(j, i) +
                  sum(select(k > i,
                             A_param(i, k) * B_param(j, k),
                             zero)));

    // ------------------------------------------------------------------
    // Schedule for trmm
    //
    // Goals:
    //   - j (columns) is the innermost dimension and contiguous in memory,
    //     so we vectorize across j.
    //   - i (rows) are independent, so we parallelize across i.
    //   - We split i into tiles to get a reasonable amount of work per task.
    // ------------------------------------------------------------------
    Target target = get_host_target();
    const int vec = target.natural_vector_size(type_of<num_t>());

    // Outer/inner tiles in the i (row) dimension.
    Var io("io"), ii("ii");

    trmm
        .compute_root()                 // materialize trmm as a top-level loop nest
        .split(i, io, ii, 32)           // tiles of 32 rows
        // Set loop nest order explicitly:
        //   outermost: io  (row tiles, parallel)
        //   then:      ii  (rows inside tile)
        //   innermost: j   (columns, vectorized)
        .reorder(j, ii, io)
        .parallel(io)
        .vectorize(j, vec);

    // Compile the kernel to machine code (JIT).
    trmm.compile_jit(target);

    // Output buffer for the result (same logical layout as B)
    Buffer<num_t, 2> B_result(n, m);

    // Time the execution (only the actual realization is timed; JIT is done above).
    auto start = std::chrono::high_resolution_clock::now();

    trmm.realize(B_result);

    auto end = std::chrono::high_resolution_clock::now();
    auto duration = std::chrono::duration<long double>(end - start);

    // Optionally print the result to avoid dead-code elimination
    using namespace std::string_literals;
