 *   - B is declared in C as B[m][n] and accessed as B[i][j].
 *     We store it as Buffer B(width=n, height=m) and access as B(j, i).
 */
static void init_array(int m, int n,
                       num_t *alpha,
                       Halide::Buffer<num_t, 2> A,
                       Halide::Buffer<num_t, 2> B) {
    *alpha = static_cast<num_t>(1.5);

    Var i("i"), j("j");
    Func init_A("init_A"), init_B("init_B");

    // Make Expr versions of m and n for use inside Halide expressions.
    Expr m_expr = Expr(m);
    Expr n_expr = Expr(n);

    // A(i,j):
    //   For j < i:  ( (i + j) % m ) / m
    //   For j == i: 1.0
    //   For j > i:  0.0 (never used by the kernel, but we define it anyway)
    init_A(j, i) =
        select(j < i,
               cast<num_t>((i + j) % m_expr) / cast<num_t>(m_expr),
               select(j == i,
                      cast<num_t>(1.0),
                      cast<num_t>(0.0)));

    // B(i,j): ( (n + (i - j)) % n ) / n
    init_B(j, i) =
        cast<num_t>((n_expr + (i - j)) % n_expr) / cast<num_t>(n_expr);

    // Simple CPU schedule for initialization:
    //  - Parallelize across rows (i)
    //  - Vectorize across columns (j)
    Target target = get_host_target();
    const int vec_width = target.natural_vector_size(type_of<num_t>());

    init_A
        .compute_root()
        .bound(i, 0, m)
        .bound(j, 0, m)
        .parallel(i)
        .vectorize(j, vec_width);

    init_B
        .compute_root()
        .bound(i, 0, m)
        .bound(j, 0, n)
        .parallel(i)
        .vectorize(j, vec_width);

    // Realize into the supplied buffers.
    init_A.realize(A, target);
    init_B.realize(B, target);
}

int main(int argc, char *argv[]) {
    // Problem sizes (compile-time constants from PolyBench headers)
    int m = M;
    int n = N;

    // Scalars and arrays
    num_t alpha;
    // Buffer layout: width = number of columns, height = number of rows
    // A: M x M  -> Buffer(m, m) accessed as A(j, i) == A[i][j] in C
    // B: M x N  -> Buffer(n, m) accessed as B(j, i) == B[i][j] in C
    Buffer<num_t, 2> A(m, m);
    Buffer<num_t, 2> B(n, m);

    // Initialize data
    init_array(m, n, &alpha, A, B);

    // Halide ImageParams corresponding to A and B (read-only views)
    ImageParam A_param(type_of<num_t>(), 2, "A_param");
    ImageParam B_param(type_of<num_t>(), 2, "B_param");
    A_param.set(A);
    B_param.set(B);

    // Make the assumed bounds explicit (helps bounds inference & enables
    // some scheduling optimizations to be safely applied).
    A_param.dim(0).set_bounds(0, m);  // columns
    A_param.dim(1).set_bounds(0, m);  // rows
    B_param.dim(0).set_bounds(0, n);  // columns
    B_param.dim(1).set_bounds(0, m);  // rows

    // Vars
    Var i("i"), j("j");

    // Func representing the result B := alpha * A^T * B
    //
    // Original kernel:
    //
    // for (i = 0; i < M; i++)
    //   for (j = 0; j < N; j++) {
    //     for (k = i+1; k < M; k++)
    //       B[i][j] += A[k][i] * B[k][j];
    //     B[i][j] = alpha * B[i][j];
    //   }
    //
    // As argued in the original code, B[k][j] is always read from the
    // original B, so each (i,j) is independent and we can safely express:
    //
    //   B_out[i][j] = ( B_in[i][j] +
    //                   sum_{k = i+1..M-1} A[k][i] * B_in[k][j] ) * alpha
    //
    // Mapping indices to Halide:
    //   A[k][i]  -> A_param(i, k)
    //   B[k][j]  -> B_param(j, k)
    //   B[i][j]  -> B_param(j, i)
    //
    // Instead of an RDom over [0..M-1] with a select(k > i, ...),
    // we use an RDom whose min and extent depend on i:
    //   k in [i+1, M-1]
    // This avoids useless iterations and unnecessary branches.
    Func trmm("trmm");

    Expr alpha_expr = cast<num_t>(alpha);

    // Pure definition: start from the original B[i][j].
    trmm(j, i) = B_param(j, i);

    // Reduction over k = i+1 .. M-1.
    RDom k(i + 1, m - (i + 1), "k");
    trmm(j, i) += A_param(i, k) * B_param(j, k);

    // Final scaling by alpha, done as a separate update step so we
    // match the original C kernel's operation ordering:
    //   accumulate, then multiply once by alpha.
    trmm(j, i) *= alpha_expr;

    // ------------------------------------------------------------------
    // Scheduling
    // ------------------------------------------------------------------
    Target target = get_host_target();
    const int vec_width = target.natural_vector_size(type_of<num_t>());

    // Compute the entire result at root.
    trmm.compute_root();

    // Explicit bounds to help Halide reason about extents.
    trmm
        .bound(i, 0, m)
        .bound(j, 0, n);

    // Parallelize across rows (i == C's outer loop), and vectorize
    // across columns (j == fastest-varying dimension).
    //
    // This matches the original loop nest order:
    //   for (i = 0; i < M; i++)    // parallel
    //     for (j = 0; j < N; j++)  // vectorized
    trmm
        .parallel(i)
        .vectorize(j, vec_width);

    // Apply the same strategy to all update stages:
    //  - update(0): the k-reduction
    //  - update(1): the final multiply by alpha
    trmm.update(0)
        .parallel(i)
        .vectorize(j, vec_width);

    trmm.update(1)
        .parallel(i)
        .vectorize(j, vec_width);

    // Compile the kernel to machine code for the chosen target.
    trmm.compile_jit(target);

    // Output buffer for the result (same logical layout as B)
    Buffer<num_t, 2> B_result(n, m);

    // Time the execution (kernel only; JIT-compilation is excluded)
    auto start = std::chrono::high_resolution_clock::now();

    trmm.realize(B_result, target);

    auto end = std::chrono::high_resolution_clock::now();
    auto duration = std::chrono::duration<long double>(end - start);

    // Optionally print the result to avoid dead-code elimination
    using namespace std::string_literals;
    if (argc > 0 && argv[0] != ""s) {
        std::cerr << std::fixed << std::setprecision(2);
        for (int ii = 0; ii < m; ii++) {
            for (int jj = 0; jj < n; jj++) {
                // Remember: B_result(jj, ii) == B[ii][jj] in the original C code
                std::cerr << B_result(jj, ii) << '\n';
            }
        }
    }

    // Print elapsed time in seconds
    std::cout << std::fixed << std::setprecision(6);
    std::cout << duration.count() << std::endl;

    return 0;
}
